def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return min(budget, 18.0)

    slots = supply / float(WATER_REQ)
    pressure = len(alive) + 1 - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if pressure >= 2.0:
        danger += 2
    elif pressure >= 1.0:
        danger += 1

    if rich_opp >= 2:
        danger += 1
    if urgent_opp >= 1:
        danger += 1

    if highest_prev >= 140:
        market = 'very_high'
    elif highest_prev >= 110:
        market = 'high'
    elif highest_prev >= 70:
        market = 'mid'
    else:
        market = 'low'

    if danger >= 6:
        if market == 'very_high':
            bid = highest_prev + 2.5
        elif market == 'high':
            bid = max(108.0, highest_prev + 2.0)
        elif market == 'mid':
            bid = max(82.0, highest_prev + 3.0)
        else:
            bid = 76.0
    elif danger >= 4:
        if market == 'very_high':
            bid = max(92.0, highest_prev * 0.78)
        elif market == 'high':
            bid = max(74.0, avg_prev + 4.0)
        elif market == 'mid':
            bid = max(58.0, highest_prev + 2.0)
        else:
            bid = 49.0
    elif danger >= 2:
        if slots >= 2.0:
            bid = 26.0
        elif market == 'very_high':
            bid = 34.0
        elif market == 'high':
            bid = 42.0
        elif market == 'mid':
            bid = 37.0
        else:
            bid = 28.0
    else:
        if slots >= 2.0:
            bid = 12.0
        else:
            bid = 19.0

    if budget < bid:
        if hp <= 2 or no_water >= 2:
            bid = budget
        else:
            bid = min(budget, max(0.0, budget * 0.55))

    if hp >= 8 and no_water == 0 and slots >= 1.8 and highest_prev >= 120:
        bid = min(bid, 18.0)

    if budget <= 25 and (hp > 3 and no_water == 0):
        bid = min(bid, 10.0)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.9: 
            if my_hp <= 3: 
                base_bid = max(DAILY_SALARY * 0.98, highest_prev_bid + 5)
            elif my_hp <= 5: 
                base_bid = max(DAILY_SALARY * 0.9, highest_prev_bid + 2)
            else: 
                base_bid = max(DAILY_SALARY * 0.8, highest_prev_bid + 1)
        elif highest_prev_bid >= DAILY_SALARY * 0.75: 
            if my_hp <= 3: 
                base_bid = max(DAILY_SALARY * 0.95, highest_prev_bid + 5)
            else: 
                base_bid = max(DAILY_SALARY * 0.78, highest_prev_bid + 2)
        else: 
            if my_hp <= 3: 
                base_bid = max(DAILY_SALARY * 0.9, highest_prev_bid + 10)
            elif my_hp <= 5: 
                base_bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 5)
            else: 
                base_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1)
    else: 
        if my_hp <= 3:
            base_bid = DAILY_SALARY * 0.95
        elif my_hp <= 5:
            base_bid = DAILY_SALARY * 0.85
        else:
            base_bid = DAILY_SALARY * 0.7

    if current_day >= EPISODE_DAYS - 2 and my_hp <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.98)

    if my_hp >= 9 and current_day < EPISODE_DAYS / 2:
        base_bid = min(base_bid, DAILY_SALARY * 0.7)

    bid = min(my_budget, base_bid)
    bid = max(bid, DAILY_SALARY * 0.2)

    return bid
